const r=require('./round-fixes.js');
const A=q=>r.verifiedRoundAnswer(r.normalizeQuestion(q),{});
const yes=[
['辦公室借用別人的地方行不行','同意書'],['會址可以借別人的嗎','同意書'],['會址一定要租嗎','不一定'],['協會辦公室一定要買嗎','不一定'],
['會所沒有固定地點可以嗎','第12條'],['協會可以沒有會址嗎','不可以'],
['會址搬到別的縣市怎麼辦','第6條'],['協會要搬去外縣市可以嗎','核准'],
['想看協會章程去哪找','索取'],['章程哪裡可以看','索取'],
['修章程要多少人出席才算數','過半數'],['改章程出席人數要幾人才有效','三分之二'],
['章程裡理事人數可以改嗎','十五人'],['協會的理事名額能不能調整','第17條'],
['沒照章程做會怎樣','第58條'],['不依章程辦理會有什麼後果','撤銷'],
['章程裡的會費可以自己調嗎','第33條'],['常年會費可以調漲嗎','會員（會員代表）大會'],
['會址跟章程寫的不一樣會怎樣','補辦'],['忘記把新地址報給縣府怎麼辦','盡快補辦'],['漏報會址搬家怎麼辦','備查'],
['章程條文看不懂可以問誰','理事長']];
const no=['合作社章程怎麼改','社區發展協會會址可以設在住家嗎','章程弄丟了怎麼補','章程範本去哪下載','修改章程要開什麼會','工會會費可以調嗎','理事人數最少幾人','協會會址可以設在理事長家裡嗎','會員欠會費怎麼辦','協會名稱想改要怎麼弄','基金會會址要借別人的可以嗎'];
const mine=/^(會址借用別人|會址一定要租|協會可以沒有會址|會址搬到外縣市|想看某協會|修改章程要多少人|理事、監事人數可以改|協會沒有照章程|會費可以調整|會址和章程寫的|忘記報新會址|章程看不懂)/;
let bad=0;
yes.forEach(([q,e])=>{const a=A(q);const x=a&&a.title?(a.title+a.summary):'';if(!x.includes(e)||!a.direct){bad++;console.log('✗',q,a&&a.title)}});
no.forEach(q=>{const a=A(q);if(a&&a.title&&mine.test(a.title)){bad++;console.log('✗誤觸',q,a.title)}});
console.log(bad?'失敗 '+bad:'全部通過');process.exit(bad?1:0);
